-- H2-04 Pharma OA workflow-linked business records. Normal uninstall policy: retain.
CREATE TABLE IF NOT EXISTS pharma_oa_contracts (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, title VARCHAR(255) NOT NULL, party_type VARCHAR(32) NOT NULL, party_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, workflow_instance_id VARCHAR(64) NOT NULL, owner_id VARCHAR(64) NOT NULL, approver_id VARCHAR(64) NOT NULL, amount DECIMAL(18,2) NOT NULL, currency VARCHAR(16) NOT NULL, effective_at DATETIME(3) NOT NULL, expires_at DATETIME(3) NOT NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_contracts_number(number), KEY idx_pharma_contracts_party_status(party_type,party_id,status), KEY idx_pharma_contracts_expiry(expires_at,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_quality_complaints (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, title VARCHAR(255) NOT NULL, customer_id VARCHAR(64) NOT NULL, product_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, workflow_instance_id VARCHAR(64) NOT NULL, reporter_id VARCHAR(64) NOT NULL, handler_id VARCHAR(64) NOT NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_complaints_number(number), KEY idx_pharma_complaints_status_product(status,product_id), KEY idx_pharma_complaints_batch(batch_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_drug_recalls (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, title VARCHAR(255) NOT NULL, product_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, source_complaint_id VARCHAR(64) NOT NULL DEFAULT '', status VARCHAR(32) NOT NULL, initiated_by VARCHAR(64) NOT NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_recalls_number(number), KEY idx_pharma_recalls_batch_status(batch_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_customer_follow_ups (id VARCHAR(64) PRIMARY KEY, customer_id VARCHAR(64) NOT NULL, customer_code VARCHAR(128) NOT NULL, customer_name VARCHAR(255) NOT NULL, owner_id VARCHAR(64) NOT NULL, organization_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, scheduled_at DATETIME(3) NOT NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', KEY idx_pharma_followups_scope_status(organization_id,owner_id,status), KEY idx_pharma_followups_customer_time(customer_id,scheduled_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_sales_opportunities (id VARCHAR(64) PRIMARY KEY, title VARCHAR(255) NOT NULL, customer_id VARCHAR(64) NOT NULL, customer_code VARCHAR(128) NOT NULL, customer_name VARCHAR(255) NOT NULL, owner_id VARCHAR(64) NOT NULL, organization_id VARCHAR(64) NOT NULL, stage VARCHAR(32) NOT NULL, expected_amount_cents BIGINT NOT NULL, estimated_close_date DATETIME(3) NOT NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', KEY idx_pharma_opportunities_scope_stage(organization_id,owner_id,stage), KEY idx_pharma_opportunities_customer(customer_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_payment_plans (id VARCHAR(64) PRIMARY KEY, sales_order_id VARCHAR(64) NOT NULL, sales_order_number VARCHAR(128) NOT NULL, customer_id VARCHAR(64) NOT NULL, owner_id VARCHAR(64) NOT NULL, order_total_cents BIGINT NOT NULL, amount_cents BIGINT NOT NULL, paid_amount_cents BIGINT NOT NULL, status VARCHAR(32) NOT NULL, due_at DATETIME(3) NOT NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_payment_plan_order(sales_order_id), KEY idx_pharma_payment_plan_due_status(status,due_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_invoice_records (id VARCHAR(64) PRIMARY KEY, number VARCHAR(128) NOT NULL, sales_order_id VARCHAR(64) NOT NULL, sales_order_number VARCHAR(128) NOT NULL, customer_id VARCHAR(64) NOT NULL, owner_id VARCHAR(64) NOT NULL, order_total_cents BIGINT NOT NULL, amount_cents BIGINT NOT NULL, status VARCHAR(32) NOT NULL, issued_at DATETIME(3) NOT NULL, voided_at DATETIME(3) NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_invoices_number(number), KEY idx_pharma_invoices_order_status(sales_order_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_payment_reminder_jobs (id VARCHAR(64) PRIMARY KEY, status VARCHAR(32) NOT NULL, recipient_id VARCHAR(64) NOT NULL, owner_id VARCHAR(64) NOT NULL DEFAULT '', initiated_by VARCHAR(64) NOT NULL, last_run_by VARCHAR(64) NOT NULL, retry_count INT NOT NULL, error VARCHAR(1024) NOT NULL DEFAULT '', started_at DATETIME(3) NULL, completed_at DATETIME(3) NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', KEY idx_pharma_payment_reminder_jobs_status_created(status,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_inventory_alerts (id VARCHAR(64) PRIMARY KEY, type VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, balance_id VARCHAR(64) NOT NULL, product_id VARCHAR(64) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, recipient_id VARCHAR(64) NOT NULL, notification_id VARCHAR(128) NOT NULL, last_seen_at DATETIME(3) NOT NULL, resolved_at DATETIME(3) NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_inventory_alert_position(type,balance_id), KEY idx_pharma_inventory_alerts_status_seen(status,last_seen_at), KEY idx_pharma_inventory_alerts_status_type_seen(status,type,last_seen_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_inventory_alert_jobs (id VARCHAR(64) PRIMARY KEY, status VARCHAR(32) NOT NULL, idempotency_key VARCHAR(191) NOT NULL, retry_count INT NOT NULL, error VARCHAR(1024) NOT NULL DEFAULT '', started_at DATETIME(3) NULL, completed_at DATETIME(3) NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_alert_jobs_idempotency(idempotency_key), KEY idx_pharma_alert_jobs_status_created(status,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_report_export_jobs (id VARCHAR(64) PRIMARY KEY, report_type VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, owner_id VARCHAR(64) NOT NULL, idempotency_key VARCHAR(191) NOT NULL, retry_count INT NOT NULL, file_id VARCHAR(64) NOT NULL DEFAULT '', error VARCHAR(1024) NOT NULL DEFAULT '', started_at DATETIME(3) NULL, completed_at DATETIME(3) NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', UNIQUE KEY uk_pharma_export_jobs_idempotency(idempotency_key), KEY idx_pharma_export_jobs_status_created(status,created_at), KEY idx_pharma_export_jobs_owner_status_created(owner_id,status,created_at)) ENGINE=InnoDB;
